SUMMARY = t('Advanced and Collective Protection (AI): a behaviour scorer, signed models, shared indicators (3 firewalls or confirmed by Nexwall), a new page to control them, and usage measurement for the license size.',
            'Protección Avanzada y Colectiva (IA): un evaluador de comportamiento, modelos firmados, indicadores compartidos (3 firewalls o confirmados por Nexwall), una página nueva para controlarlos y medición de uso para el tamaño de la licencia.',
            'Proteção Avançada e Coletiva (IA): um avaliador de comportamento, modelos assinados, indicadores compartilhados (3 firewalls ou confirmados pela Nexwall), uma página nova para controlá-los e medição de uso para o tamanho da licença.')
OVERVIEW_PREFIX = t(
 'Nexwall Firewall 26.2.1 adds Advanced Protection and Collective Protection (AI) to the 26.1.3 firewall, with one page to control and watch them in Protection Services. It also measures the active devices and the throughput for the license size, and keeps all the 26.1.3 fixes. ',
 'Nexwall Firewall 26.2.1 añade la Protección Avanzada y la Protección Colectiva (IA) al firewall 26.1.3, con una página para controlarlas y observarlas en Servicios de protección. También mide los dispositivos activos y el caudal para el tamaño de la licencia, y conserva todas las correcciones de la 26.1.3. ',
 'O Nexwall Firewall 26.2.1 acrescenta a Proteção Avançada e a Proteção Coletiva (IA) ao firewall 26.1.3, com uma página para controlá-las e observá-las em Serviços de proteção. Também mede os dispositivos ativos e a vazão para o tamanho da licença, e mantém todas as correções da 26.1.3. ')
STATUS = t('Release candidate until the images are built and tested', 'Candidata hasta que las imágenes estén construidas y probadas', 'Candidata até as imagens serem construídas e testadas')
TIMELINE = t(('2026-10-20', 'From 26.1.3 to 26.2.1', 'Advanced Protection and Collective Protection (AI) with their page, signed model distribution, shared indicators and review, usage measurement, license component 1.9.0, web interface 3.1.0, and the web proxy fixes proved again.'),
             ('2026-10-20', 'De 26.1.3 a 26.2.1', 'Protección Avanzada y Protección Colectiva (IA) con su página, distribución firmada de modelos, indicadores compartidos y revisión, medición de uso, componente de licencia 1.9.0, interfaz web 3.1.0 y las correcciones del proxy web probadas de nuevo.'),
             ('2026-10-20', 'De 26.1.3 a 26.2.1', 'Proteção Avançada e Proteção Coletiva (IA) com sua página, distribuição assinada de modelos, indicadores compartilhados e revisão, medição de uso, componente de licença 1.9.0, interface web 3.1.0 e as correções do proxy web testadas de novo.'))
COMP = [('Advanced Protection scorer', DATA['atp'], t('Behaviour scorer with signed models; advisory events only', 'Evaluador de comportamiento con modelos firmados; solo eventos de aviso', 'Avaliador de comportamento com modelos assinados; apenas eventos de aviso')),
        ('Collective Protection lists', 'atp_ip, atp_dns', t('Threat-list categories fed by reports reviewed by Nexwall; refreshed with the threat lists', 'Categorías de listas de amenazas alimentadas por informes revisados por Nexwall; se actualizan con las listas de amenazas', 'Categorias de listas de ameaças alimentadas por relatórios revisados pela Nexwall; atualizadas com as listas de ameaças'))]
PRIV = t(('Reports shared by the firewall (Collective Protection)',
          'Firewalls with Advanced and Collective Protection (AI) can send reports about suspicious external addresses and domains. Switch: on by default, can be switched off at any time on the Advanced and Collective Protection (AI) page. What is sent: the external address or domain, the kind of behaviour, a score, the date and the identity of the firewall (a device token and a signature). What is never sent: the content of traffic, files, user names, internal addresses, browsing history. Purpose: to protect all customers, by publishing an indicator when at least 3 different firewalls reported it or when the Nexwall team confirmed it; published indicators expire after 14 days. Legal basis: legitimate interest in network security (LGPD article 7, IX) and fraud prevention and security of the holder (article 11, II, g, where applicable). Reports are kept on servers in Brazil for as long as the indicator is valid and up to 12 months for the review history. Contact the data protection officer for any request. [DRAFT: to be reviewed by the owner and legal counsel before the release is published.]'),
         ('Informes compartidos por el firewall (Protección Colectiva)',
          'Los firewalls con Protección Avanzada y Colectiva (IA) pueden enviar informes sobre direcciones externas y dominios sospechosos. Interruptor: activado por defecto, se puede desactivar en cualquier momento en la página Protección Avanzada y Colectiva (IA). Qué se envía: la dirección externa o el dominio, el tipo de comportamiento, una puntuación, la fecha y la identidad del firewall (un token de dispositivo y una firma). Qué nunca se envía: el contenido del tráfico, archivos, nombres de usuario, direcciones internas, historial de navegación. Finalidad: proteger a todos los clientes, publicando un indicador cuando al menos 3 firewalls distintos lo comunicaron o cuando el equipo de Nexwall lo confirmó; los indicadores publicados caducan a los 14 días. Base legal: interés legítimo en la seguridad de la red (LGPD artículo 7, IX) y prevención del fraude y seguridad del titular (artículo 11, II, g, cuando proceda). Los informes se conservan en servidores en Brasil mientras el indicador sea válido y hasta 12 meses para el historial de revisión. Contacte al encargado de protección de datos para cualquier solicitud. [BORRADOR: debe ser revisado por el propietario y asesoría jurídica antes de publicar la versión.]'),
         ('Relatórios compartilhados pelo firewall (Proteção Coletiva)',
          'Firewalls com Proteção Avançada e Coletiva (IA) podem enviar relatórios sobre endereços externos e domínios suspeitos. Chave: ativada por padrão, pode ser desativada a qualquer momento na página Proteção Avançada e Coletiva (IA). O que é enviado: o endereço externo ou o domínio, o tipo de comportamento, uma pontuação, a data e a identidade do firewall (um token de dispositivo e uma assinatura). O que nunca é enviado: o conteúdo do tráfego, arquivos, nomes de usuário, endereços internos, histórico de navegação. Finalidade: proteger todos os clientes, publicando um indicador quando pelo menos 3 firewalls diferentes o comunicaram ou quando a equipe da Nexwall o confirmou; indicadores publicados expiram em 14 dias. Base legal: legítimo interesse na segurança da rede (LGPD artigo 7º, IX) e prevenção à fraude e segurança do titular (artigo 11, II, g, quando aplicável). Os relatórios são mantidos em servidores no Brasil enquanto o indicador for válido e por até 12 meses para o histórico de revisão. Fale com o encarregado de proteção de dados para qualquer solicitação. [RASCUNHO: deve ser revisado pelo proprietário e pela assessoria jurídica antes de publicar a versão.]'))

for lang in L:
    d = copy.deepcopy(json.load(open('content/26.1.3/%s.json' % lang)))
    d['title'] = 'Nexwall Firewall 26.2.1'
    d['summary'] = SUMMARY[lang]
    first, _, rest = d['overview'].partition('. ')
    d['overview'] = OVERVIEW_PREFIX[lang] + rest
    for row in d['at_a_glance']:
        if row['value'] == '26.1.3':
            row['value'] = '26.2.1'
    d['at_a_glance'][1]['value'] = STATUS[lang]
    i = {'en': 0, 'es': 1, 'pt-BR': 2}[lang]
    for s in d['sections']:
        if s['id'] == 'whats-new':
            s['items'] = [{'tag': 'new', 'title': x[i], 'body': x[3 + i]} for x in NEW] + s['items']
        if s['id'] == 'improvements':
            s['items'] = [{'tag': 'improved', 'title': x[i], 'body': x[3 + i]} for x in IMPROVED] + s['items']
    for r in d['components']['rows']:
        if r['name'] == 'Image':
            r['version'] = '26.2.1'
        elif r['name'] == 'Firmware sources':
            r['version'] = DATA['firmware_commit']
        elif r['name'] == 'Web interface':
            r['version'] = DATA['ui']
        elif r['name'] == 'License component':
            r['version'] = DATA['license_core']
    d['components']['rows'] += [{'name': n, 'version': v, 'note': nt[lang]} for n, v, nt in COMP]
    d['timeline']['entries'] = [{'date': TIMELINE[lang][0], 'title': TIMELINE[lang][1], 'text': TIMELINE[lang][2]}] + d['timeline']['entries']
    os.makedirs('content/26.2.1', exist_ok=True)
    json.dump(d, open('content/26.2.1/%s.json' % lang, 'w'), ensure_ascii=False, indent=2)
    open('content/26.2.1/%s.json' % lang, 'a').write('\n')
    # privacy notice: section about the shared reports (idempotent)
    lg = json.load(open('content/legal/%s.json' % lang))
    secs = lg['privacy']['sections']
    if not any(s[0] == PRIV[lang][0] for s in secs):
        secs.insert(len(secs) - 1, list(PRIV[lang]))
        json.dump(lg, open('content/legal/%s.json' % lang, 'w'), ensure_ascii=False, indent=2)
        open('content/legal/%s.json' % lang, 'a').write('\n')

if '--publish' in sys.argv:
    assert DATA['downloads'], 'downloads missing in tools_2621_data.json'
    rel = json.load(open('content/releases.json'))
    rel = [r for r in rel if r['version'] != '26.2.1']
    for r in rel:
        if r['version'] == '26.1.3':
            r['status'] = 'superseded'
    rel.insert(0, {'version': '26.2.1', 'date': DATA['date'], 'status': 'stable', 'downloads': DATA['downloads']})
    json.dump(rel, open('content/releases.json', 'w'), ensure_ascii=False, indent=1)
    open('content/releases.json', 'a').write('\n')
print('26.2.1 written')
